def transform(grid):
    """Find the rare foreground color's shape and mark each all-zero translated copy."""
    src = [row[:] for row in grid]
    h, w = len(src), len(src[0])
    counts = {}
    for row in src:
        for value in row:
            if value != 0:
                counts[value] = counts.get(value, 0) + 1
    if not counts:
        return src
    color = min(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w) if src[r][c] == color]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    dh, dw = max(r for r, c in shape), max(c for r, c in shape)
    out = [row[:] for row in src]
    for r in range(h-dh):
        for c in range(w-dw):
            cells = [(r+dr, c+dc) for dr, dc in shape]
            if all(src[y][x] == 0 for y, x in cells):
                for y, x in cells:
                    out[y][x] = color
    return out
